{"command": "cat > /workdir/solve.py << 'PYEOF'
import json
import ipaddress
from datetime import datetime, timezone

RFC1918_NETWORKS = [
    ipaddress.ip_network("10.0.0.0/8"),
    ipaddress.ip_network("172.16.0.0/12"),
    ipaddress.ip_network("192.168.0.0/16"),
]

def is_private_ipv4(ip_str):
    try:
        addr = ipaddress.ip_address(ip_str)
        if addr.version != 4:
            return False
        return any(addr in net for net in RFC1918_NETWORKS)
    except:
        return False

def is_valid_ipv4(ip_str):
    try:
        addr = ipaddress.ip_address(ip_str)
        return addr.version == 4
    except:
        return False

def map_action(action):
    mapping = {
        "Successful": "allow",
        "Dropped": "drop",
        "Rejected": "deny",
        "Reset": "reset"
    }
    return mapping.get(action)

with open("/workdir/input.txt") as f:
    lines = f.readlines()

records = []

for line in lines:
    line = line.strip()
    if not line:
        continue
    parts = line.split("\t")
    if len(parts) != 7:
        continue

    ts_str, src_ip, src_port, dst_ip, dst_port, protocol, action = parts

    # Filter: protocol must be tcp or udp
    protocol = protocol.lower()
    if protocol not in ("tcp", "udp"):
        continue

    # Filter: both IPs must be valid IPv4
    if not is_valid_ipv4(src_ip) or not is_valid_ipv4(dst_ip):
        continue

    # Filter: at least one IP must be private (RFC 1918)
    if not is_private_ipv4(src_ip) and not is_private_ipv4(dst_ip):
        continue

    # Map action
    mapped_action = map_action(action)
    if not mapped_action:
        continue

    # Convert timestamp
    ts = int(ts_str)
    dt = datetime.fromtimestamp(ts, tz=timezone.utc)
    iso_ts = dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Parse port
    port = None
    if dst_port.strip():
        port = int(dst_port.strip())

    records.append({
        "timestamp": iso_ts,
        "src_ip": src_ip,
        "dst_ip": dst_ip,
        "protocol": protocol,
        "action": mapped_action,
        "port": port,
        "_ts": ts  # for dedup ordering
    })

# Deduplication: keep last occurrence of each flow
seen_flows = {}
for i, rec in enumerate(records):
    flow_key = (rec["src_ip"], rec["dst_ip"], rec["protocol"], rec["port"])
    seen_flows[flow_key] = i  # keep updating to last occurrence

result = [records[i] for i in seen_flows.values()]

# Remove internal _ts field
for rec in result:
    del rec["_ts"]

# Sort by timestamp, then by other fields for consistency
result.sort(key=lambda r: (r["timestamp"], r["src_ip"], r["dst_ip"], r["protocol"], r["port"] if r["port"] is not None else -1))

with open("/workdir/normalized.json", "w") as f:
    json.dump(result, f, indent=2)
