    flow_key = (rec["src_ip"], rec["dst_ip"], rec["protocol"], rec["port"])
    if flow_key not in flow_data:
        flow_data[flow_key] = rec
    else:
        existing = flow_data[flow_key]
        new_sev = ACTION_SEVERITY[rec["action"]]
